pub fn max_array(nums: &[i32]) -> usize {
    // Problem guarantees nums is non-empty.
    let mut best_idx: usize = 0;
    let mut best_val: i32 = nums[0];

    for i in 1..nums.len() {
        let v = nums[i];
        if v > best_val {
            best_val = v;
            best_idx = i;
        }
    }

    best_idx
}

